10	import {selectSubprotocol} from './ws/subprotocol.js';
11	import type {ConnectInfo, SessionResumeOptions} from './ws/sessionResume.js';
12	import {log} from '../shared/logger.js';
13	
14	export interface HalServerOptions {
15	  app: Express;
16	  wsAuth: WsAuthenticator;
17	  sessionStore: SessionStore;
18	  orchestrator: ChatOrchestrator;
19	  toolRegistry?: ToolRegistry;
20	  basePath?: string;
21	  port?: number;
22	  heartbeatIntervalMs?: number;
23	  onConnect?: (session: import('../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
24	  onDisconnect?: (sessionId: string) => void | Promise<void>;
25	  resume?: SessionResumeOptions;
26	}
27	
28	export interface HalServer {
29	  server: http.Server;
30	  wss: WebSocketServer;
31	  start: (port?: number) => Promise<void>;
32	  stop: () => Promise<void>;
33	}
34	
35	export function createServer(options: HalServerOptions): HalServer {
36	  const basePath = options.basePath ?? '/hal';
37	
38	  const wss = new WebSocketServer({
39	    noServer: true,
40	    handleProtocols: selectSubprotocol,
41	  });
42	
43	  const handleMessage = createMessageHandler(options.orchestrator);
44	  const examplePrompts = options.toolRegistry?.getExamplePrompts() ?? [];
45	
46	  const deps = {
47	    wsAuth: options.wsAuth,
48	    sessionStore: options.sessionStore,
49	    handleMessage,
50	    basePath,
51	    onConnect: options.onConnect,
52	    onDisconnect: options.onDisconnect,
53	    resume: options.resume,
54	  };
55	
56	  const handleUpgrade = createUpgradeHandler(wss, deps);
57	  const handleConnection = createConnectionHandler(deps, examplePrompts);
58	
