import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {createChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {ToolRegistry} from '../../orchestration/tools/registry.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {MockProvider} from '../../providers/mock.js';
import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
import type {ChatSession} from '../../types/session.js';

describe('list_sessions message handler', () => {
  it('calls store.listFor with session userId when handling list_sessions', async () => {
    const toolRegistry = new ToolRegistry();
    const promptBuilder = new PromptBuilder();
    const orchestrator = createChatOrchestrator({
      provider: new MockProvider(),
      toolRegistry,
      promptBuilder,
    });

    const calls: Array<{userId: string | number; options?: unknown}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's1',
        createdAt: new Date('2026-01-01'),
        updatedAt: new Date('2026-01-01'),
        entryCount: 0,
      },
    ];

    const sessionStore: SessionStore = {
      create: async () => 's1',
      get: async () => ({sessionId: 's1', userId: 'u1', entries: []}),
      delete: async () => {},
      count: async () => 1,
      clear: async () => {},
      listFor: async (userId, options) => {
        calls.push({userId, options});
        return summaries;
      },
    };

    const sent: unknown[] = [];
    const ws = {
      send: (msg: string) => sent.push(JSON.parse(msg)),
      readyState: WebSocket.OPEN,
    } as unknown as WebSocket;

    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [],
    };

    const handleMessage = createMessageHandler(orchestrator, sessionStore);
    await handleMessage(ws, session, {type: 'list_sessions', limit: 10});

    expect(calls).toEqual([{userId: 'u1', options: {limit: 10, before: undefined}}]);
    expect(sent).toHaveLength(1);
    expect(sent[0]).toMatchObject({
      type: 'session_list',
      sessions: expect.any(Array),
    });
  });
});

